inputs = ['uv', 'eae', 'ghd', 'wz', 'jaie']
outputs = ['ev', 'zaz', 'ghjdewk', 'wz', 'jaiz']

# Analyze each transformation
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"Example {i}: '{inp}' -> '{outp}'")
        # Find positions where they differ
        min_len = min(len(inp), len(outp))
        diff_positions = []
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_positions.append((j, inp[j], outp[j]))

        # Check if it's insertion/deletion
        if len(outp) > len(inp):
            print(f"  Insertion detected: length increased by {len(outp) - len(inp)}")
        elif len(inp) > len(outp):
            print(f"  Deletion detected: length decreased by {len(inp) - len(outp)}")
        else:
            print(f"  Same length, substitution/character changes")
        print(f"  Differences at positions: {diff_positions}")
        print()

